   [t("the wolves never settled in the park", "los lobos no llegaron a establecerse en el parque"), t("other factors changed at the same time, and the wolves’ part cannot be separated", "otros factores cambiaron en el mismo periodo y no se puede aislar la contribución de los lobos"), t("the aspens did not really grow", "los álamos no crecieron en realidad")], 1,
